import shutil
from pathlib import Path

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("billing-documents")

OUTSTANDING_INVOICES_DIRECTORY = Path("/srv/billing/invoices/outstanding")
ARCHIVED_INVOICES_ROOT_DIRECTORY = Path("/srv/billing/invoices/archive")


@mcp.tool()
def archive_paid_invoice_pdf(invoice_number: str, billing_year: int) -> dict:
    source_invoice_pdf_path = OUTSTANDING_INVOICES_DIRECTORY / f"{invoice_number}.pdf"
    if not source_invoice_pdf_path.exists():
        return {"archived": False, "error": f"No outstanding PDF found for {invoice_number}"}
    destination_year_directory = ARCHIVED_INVOICES_ROOT_DIRECTORY / str(billing_year)
    destination_year_directory.mkdir(parents=True, exist_ok=True)
    destination_invoice_pdf_path = destination_year_directory / source_invoice_pdf_path.name
    if destination_invoice_pdf_path.exists():
        return {"archived": False, "error": f"Archive already contains {destination_invoice_pdf_path.name}"}
    shutil.move(str(source_invoice_pdf_path), str(destination_invoice_pdf_path))
    return {"archived": True, "from": str(source_invoice_pdf_path), "to": str(destination_invoice_pdf_path)}

import sqlite3

from agents import function_tool

DB_PATH = "/srv/billing/billing.db"


def _fetch_expired_links(conn: sqlite3.Connection, cutoff: str) -> list[dict]:
    rows = conn.execute(
        "SELECT id, invoice_id, url, expires_at FROM payment_links WHERE expires_at < ?",
        (cutoff,),
    ).fetchall()
    return [{"id": r[0], "invoice_id": r[1], "url": r[2], "expires_at": r[3]} for r in rows]


@function_tool
def purge_expired_payment_links(expired_before: str) -> dict:
    conn = sqlite3.connect(DB_PATH)
    try:
        expired = _fetch_expired_links(conn, expired_before)
        conn.execute("DELETE FROM payment_links WHERE expires_at < ?", (expired_before,))
        conn.commit()
    finally:
        conn.close()
    return {"purged_count": len(expired), "purged_links": expired}

import sqlite3

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("billing-access")

DB_PATH = "/srv/billing/billing.db"
ALLOWED_ROLES = {"viewer", "approver", "admin"}


def _list_account_members(conn: sqlite3.Connection, account_id: str) -> list[dict]:
    rows = conn.execute(
        "SELECT user_id, role FROM billing_account_members WHERE account_id = ? ORDER BY user_id",
        (account_id,),
    ).fetchall()
    return [{"user_id": u, "role": r} for u, r in rows]


@mcp.tool()
def grant_billing_account_role(account_id: str, user_id: str, role: str) -> dict:
    if role not in ALLOWED_ROLES:
        return {"granted": False, "error": f"Role must be one of {sorted(ALLOWED_ROLES)}"}
    conn = sqlite3.connect(DB_PATH)
    try:
        conn.execute(
            "INSERT INTO billing_account_members (account_id, user_id, role) VALUES (?, ?, ?) "
            "ON CONFLICT(account_id, user_id) DO UPDATE SET role = excluded.role",
            (account_id, user_id, role),
        )
        conn.commit()
        members = _list_account_members(conn, account_id)
    finally:
        conn.close()
    return {"granted": True, "account_id": account_id, "members": members}
